import { createContext, useContext, useEffect, useState, type Dispatch, type ReactNode, type SetStateAction } from 'react';
import { useAppState } from '../../app/AppState';
import { Badge, Button, Card, CardHeader, Field, Input, Textarea } from '../../components/ui';
const tabs = ['Script', 'Native'] as const; type PromptTab = (typeof tabs)[number]; type SyntaxResult = 'idle' | 'valid' | 'invalid';
interface ExternalSession { tab: PromptTab; setTab: Dispatch<SetStateAction<PromptTab>>; json: string; setJson: Dispatch<SetStateAction<string>>; result: SyntaxResult; setResult: Dispatch<SetStateAction<SyntaxResult>> }
const Context = createContext<ExternalSession | null>(null);
export function ExternalSessionProvider({ children }: { children: ReactNode }) { const [tab,setTab]=useState<PromptTab>('Script'); const [json,setJson]=useState(''); const [result,setResult]=useState<SyntaxResult>('idle'); return <Context.Provider value={{tab,setTab,json,setJson,result,setResult}}>{children}</Context.Provider>; }
const useSession=()=>{const value=useContext(Context);if(!value)throw new Error('ExternalSessionProvider missing');return value;};
export function ExternalWorkspace(){
  const {tab,setTab,json,setJson,result,setResult}=useSession(); const {native,setNative,showNotice}=useAppState(); const [prompt,setPrompt]=useState(''); const [pending,setPending]=useState<StudioStagedImport|null>(null); const [error,setError]=useState('');const [previewSeconds,setPreviewSeconds]=useState(20);const [draftConsent,setDraftConsent]=useState(false); const stage=tab.toLowerCase();
  useEffect(()=>{let active=true;if(native&&window.studio)window.studio.freezeTask(native.project.id,stage).then(value=>{if(active)setPrompt(value.prompt)}).catch(reason=>{if(active){setError(String(reason));setPrompt('')}});else setPrompt('');return()=>{active=false};},[native,stage]);
  const change=(value:string)=>{setJson(value);setResult('idle');setPending(null);setDraftConsent(false);setError('');};
  const refreshPending=async()=>{if(!native||!window.studio||stage!=='native')return;try{const value=await window.studio.pendingMedia(native.project.id);setPending(value);setError('');}catch(reason){setError(String(reason));}};
  const validate=async()=>{try{if(!native||!window.studio)throw new Error('Open a native project first.');const value=await window.studio.stageImport(native.project.id,stage,json);setPending(value);setResult('valid');}catch(reason){setResult('invalid');setError(reason instanceof Error?reason.message:String(reason));}};
  const copy=()=>navigator.clipboard.writeText(prompt).then(()=>showNotice(`${tab} prompt copied.`)).catch(reason=>setError('Clipboard ERROR: '+String(reason)));
  const exportFile=async()=>{if(!native||!window.studio)return;const file=await window.studio.exportPrompt(native.project.id,stage);if(file)showNotice('Prompt exported: '+file);};
  return <div className="grid wide-left"><Card><CardHeader title="External task prompt" hint="Copy to ChatGPT manually · no embedded API" action={<Badge tone={native&&prompt?'mint':'amber'}>{native&&prompt?'FROZEN':'EMPTY'}</Badge>}/><div className="tabs">{tabs.map(item=><button key={item} className={tab===item?'active':''} onClick={()=>setTab(item)}>{item}</button>)}</div><pre className="prompt" data-active-prompt={tab}>{native?prompt:''}</pre>{!native&&<div className="info">EMPTY — Create/open a project to freeze a real ChatGPT task. No sample prompt is available.</div>}<div className="actions"><Button variant="primary" disabled={!native||!prompt} onClick={copy}>Copy prompt</Button><Button disabled={!native||!prompt} onClick={exportFile}>Export .md</Button><Button onClick={()=>window.open('https://chatgpt.com/','_blank','noopener,noreferrer')}>Open ChatGPT</Button></div></Card>
    <Card><CardHeader title="Import JSON workspace" hint="Strict schema · diff · explicit confirmation"/><Textarea aria-label="Import JSON" value={json} onChange={event=>change(event.target.value)} placeholder="Paste the returned JSON here…"/><div className="actions"><Button disabled={!json} onClick={()=>change('')}>Clear</Button><Button variant="primary" disabled={!native||!json} onClick={validate}>Validate import</Button></div>
      {result==='valid'&&<div className="info success">Schema valid. Review the staged diff before import.</div>}{result==='invalid'&&<div className="info error" role="alert">Invalid import. {error}</div>}
      {pending&&<><div className="diff-grid"><pre className="prompt">BEFORE{`\n`}{JSON.stringify(pending.before,null,2)}</pre><pre className="prompt">AFTER{`\n`}{JSON.stringify(pending.after,null,2)}</pre></div>
        {stage==='native'&&<><div className="info">Original Mode B validates the selected sample with --seconds N. FULL_READY requires separate unscoped native validation. Media outside the scoped sample may remain incomplete only for an explicitly approved draft.</div>
          <Field label="Owner-selected preview seconds (1–60)"><Input type="number" min={1} max={60} value={previewSeconds} onChange={event=>setPreviewSeconds(Number(event.target.value))}/></Field>
          <label className="check"><input type="checkbox" checked={draftConsent} onChange={event=>setDraftConsent(event.target.checked)}/> I explicitly authorize an incomplete SAMPLE_READY draft, not full-film readiness.</label>
          <Button onClick={refreshPending}>Refresh missing media after mapping</Button>
          {pending.missing?.length? <div className="info">Unresolved native targets: {pending.missing.map(item=>item.key+' ('+item.path+')').join(', ')}. Select each precise target in Storyboard; only in-scope missing media blocks the sample.</div>:<div className="info success">No unresolved file targets recorded; the original scoped/full CLI will still verify native integrity.</div>}
        </>}
        <Button variant="primary" onClick={async()=>{if(!window.studio||!native)return;try{const state=await window.studio.confirmImport(native.project.id,pending.token,stage==='native'?{previewSeconds,allowSampleDraft:draftConsent}:undefined);setNative(state);setPending(null);setError('');showNotice(stage==='native'?(state.nativeReadiness?.fullReady?'FULL_READY · original native validator PASS.':'SAMPLE_READY draft · not full render ready.'):`${tab} revision imported.`);}catch(reason){setResult('invalid');setError(String(reason));}}}>Confirm reviewed import {stage==='native'?'(original native CLI validation)':''}</Button>
      </>}
      {error&&result!=='invalid'&&<div className="info error" role="alert">{error}</div>}{native?.nativeReadiness&&<div className="info">Current native readiness: {native.nativeReadiness.fullReady?'FULL_READY':native.nativeReadiness.sampleReady?'SAMPLE_READY draft':'NOT_READY'} · verified range {native.nativeReadiness.checkedSeconds??'ERROR'}s · latest requested {native.nativeReadiness.previewSeconds}s.</div>}
      {!native&&<div className="info">Open a project to create and import an actual frozen task. No demo import is available.</div>}
    </Card></div>;
}
